//! KEM traits for using the rustcrypto `p256` and `p384` implementations
//! consistently with `x25519_dalek` and `ml_kem`.
//!
//! (Once `dkhem` and `kem` are stable, we could use that instead.)

use crate::{rng::DynRandom, Fail};
// ml-kem 0.3: EncapsulationKey/DecapsulationKey sono top-level e i trait
// vivono in ml_kem::kem (Kem, Encapsulate, Decapsulate, TryKeyInit, KeyExport).
use ml_kem::kem::{Decapsulate as _, Encapsulate as _, Kem as _, KeyExport as _, TryKeyInit as _};

/// A vector that we assemble with a known fixed size.
///
/// Rustls requires several types (`key_exchange` shares and shared
/// secrets) to be built as a `Vec<u8>`.  Since some of these
/// are sensitive, we want to create the vector with the
/// intended capacity, and make sure that we don't do any reallocations
/// that could leave un-cleared data on the heap.
pub(crate) struct ByteVec {
    /// The output length that we expect.
    output_len: usize,
    /// The underlying Vec.
    v: Vec<u8>,
}

impl ByteVec {
    /// Create a new `ByteVec` with a given capacity.
    pub(crate) fn new(cap: usize) -> Self {
        Self {
            output_len: cap,
            v: Vec::with_capacity(cap),
        }
    }

    /// Add a slice to the end of the `ByteVec`.
    pub(crate) fn push(&mut self, s: &[u8]) {
        self.v.extend(s);
    }

    /// Consume this ByteVec and return a Vec.
    ///
    /// # Panics
    ///
    /// Panics if the vector's length is not the original capacity
    /// passed to `ByteVec::new`.
    pub(crate) fn into_vec(self) -> Vec<u8> {
        assert_eq!(self.v.len(), self.output_len);
        self.v
    }
}

/// A decapsulation key (private) for use with a KEM.
pub(crate) trait DecapKey: Sized {
    /// The corresponding encapsulation key.
    type PublicKey: EncapKey;

    /// The (fixed) length in bytes of the secret key encapsulated
    /// with this KEM.
    const SECRET_LEN: usize;

    /// Return the length in bytes of the secret key encapsulated with this KEM.
    fn secret_len(&self) -> usize {
        Self::SECRET_LEN
    }

    /// Generate a new random secret key from an RNG.
    ///
    /// (We're tied to `rand_core` 0.6 here based on the current stable versions of
    /// our EC and MLKEM implementations.)
    fn from_rng(rng: &mut DynRandom) -> (Self, Self::PublicKey);

    /// Perform a key decapsulation operation from the ciphertext in `msg`,
    /// appending the shared secret to `output`.
    fn decapsulate(self, msg: &[u8], output: &mut ByteVec) -> Result<(), Fail>;
}

/// An encapsulation (public) key for use with a KEM.
pub(crate) trait EncapKey: Sized {
    /// The length of this key when encoded.
    const PUBKEY_LEN: usize;

    /// The length of ciphertext generated by this KEM.
    const CIPHERTEXT_LEN: usize;

    /// Try to decode `input` as a public key of this type.
    fn decode(input: &[u8]) -> Result<Self, Fail>;

    /// Encode this key onto the end of `output`.
    fn encode(&self, output: &mut ByteVec);

    /// Perform a key encapsulation operation for this key,
    /// appending the ciphertext to `msg` and the shared secret to `secret_key`.
    fn encapsulate(
        &self,
        rng: &mut DynRandom,
        msg: &mut ByteVec,
        secret_key: &mut ByteVec,
    ) -> Result<(), Fail>;
}

/// Implement the KEM traits etc for x25519-dalek.
#[cfg(feature = "x25519")]
mod x25519_imp {
    use super::{ByteVec, DecapKey, DynRandom, EncapKey, Fail};
    use x25519_dalek::{EphemeralSecret, PublicKey};

    impl DecapKey for EphemeralSecret {
        type PublicKey = PublicKey;
        const SECRET_LEN: usize = 32;
        fn from_rng(rng: &mut DynRandom) -> (Self, Self::PublicKey) {
            let sk = Self::random_from_rng(rng);
            let pk = (&sk).into();
            (sk, pk)
        }
        fn decapsulate(self, msg: &[u8], output: &mut ByteVec) -> Result<(), Fail> {
            let m: &[u8; 32] = msg.try_into().map_err(|_| Fail)?;
            let their_pk = PublicKey::from(*m);
            let ss = self.diffie_hellman(&their_pk);
            if ss.was_contributory() {
                output.push(ss.as_bytes());
                Ok(())
            } else {
                Err(Fail)
            }
        }
    }

    impl EncapKey for PublicKey {
        const PUBKEY_LEN: usize = 32;
        const CIPHERTEXT_LEN: usize = 32;

        fn decode(input: &[u8]) -> Result<Self, Fail> {
            let m: &[u8; 32] = input.try_into().map_err(|_| Fail)?;
            Ok(PublicKey::from(*m))
        }

        fn encode(&self, output: &mut ByteVec) {
            output.push(self.as_bytes().as_slice());
        }

        fn encapsulate(
            &self,
            rng: &mut DynRandom,
            msg: &mut ByteVec,
            secret_key: &mut ByteVec,
        ) -> Result<(), Fail> {
            let my_sk = EphemeralSecret::random_from_rng(rng);
            let my_pk = PublicKey::from(&my_sk);
            let ss = my_sk.diffie_hellman(self);
            if ss.was_contributory() {
                msg.push(my_pk.as_bytes());
                secret_key.push(ss.as_bytes());
                Ok(())
            } else {
                Err(Fail)
            }
        }
    }
}

/// Implement KEM traits for a NIST eliptic curve.
#[cfg(any(feature = "p256", feature = "p384"))]
macro_rules! define_nist_imp {
    {
        // Module/crate for the elliptic curve.
        ec_mod: $ec_mod:ident,
        // Length of the public key, in bytes.
        pk_len: $pk_len:expr,
        // Length of the shared secret, in bytes.
        ss_len: $ss_len:expr
    } => {
        impl DecapKey for $ec_mod::ecdh::EphemeralSecret {
            type PublicKey = $ec_mod::PublicKey;
            const SECRET_LEN: usize = $ss_len;

            fn from_rng(
                rng: &mut DynRandom,
            ) -> (Self, Self::PublicKey) {
                let sk = Self::random(rng);
                let pk = sk.public_key();
                (sk,pk)
            }

            fn decapsulate(self, msg: &[u8], output: &mut ByteVec) -> Result<(), Fail>
            {
                let their_pk = $ec_mod::PublicKey::from_sec1_bytes(msg)
                    .map_err(|_| Fail)?;
                // don't need to test for noncontributory behavior here
                // since the PublicKey::from_sec1_bytes implementation
                // already checked for the identity.
                let ss = self.diffie_hellman(&their_pk);
                output.push(ss.raw_secret_bytes().as_ref());
                Ok(())
            }
        }

        impl EncapKey for $ec_mod::PublicKey {
            const PUBKEY_LEN: usize = $pk_len;
            const CIPHERTEXT_LEN: usize = $pk_len;

            fn decode(input: &[u8]) -> Result<Self, Fail> {
                $ec_mod::PublicKey::from_sec1_bytes(input)
                    .map_err(|_| Fail)
            }

            fn encode(&self, output: &mut ByteVec) {
                let encoded = $ec_mod::EncodedPoint::from(self);
                output.push(encoded.as_bytes())
            }

            fn encapsulate(
                &self,
                rng: &mut DynRandom,
                msg: &mut ByteVec,
                secret_key: &mut ByteVec,
            ) -> Result<(), Fail> {
                let my_sk = $ec_mod::ecdh::EphemeralSecret::random(rng);
                let my_pk = my_sk.public_key();
                let ss = my_sk.diffie_hellman(self);
                my_pk.encode(msg);
                secret_key.push(ss.raw_secret_bytes().as_ref());
                Ok(())
            }
        }
    }
}

#[cfg(feature = "p256")]
define_nist_imp! {
    ec_mod: p256,
    pk_len: 65,
    ss_len: 32
}

#[cfg(feature = "p384")]
define_nist_imp! {
    ec_mod: p384,
    pk_len: 97,
    ss_len: 48
}

/// Implement the KEM traits for an MLKEM
macro_rules! define_mlkem_imp {
    {
        // The mlkem parameters object.
        mlkem: $mlkem:ty,
        // The length of an encapsulattion key, encoded.
        pk_len: $pk_len:expr,
        // The length of the ciphertext.
        ctext_len: $ctext_len:expr
    } => {
        impl DecapKey for ml_kem::DecapsulationKey<$mlkem> {
            type PublicKey = ml_kem::EncapsulationKey<$mlkem>;
            const SECRET_LEN: usize = 32;

            fn from_rng (
                rng: &mut DynRandom,
            ) -> (Self, Self::PublicKey) {
                // ml-kem 0.3: la keypair si genera sul parameter set
                // (`MlKem768` implementa kem::Kem).
                <$mlkem>::generate_keypair_from_rng(rng)
            }

            fn decapsulate(self, msg: &[u8], output: &mut ByteVec) -> Result<(), Fail> {
                // ml-kem 0.3: decapsulate_slice valida la lunghezza del
                // ciphertext; la decapsulation vera e' infallibile
                // (implicit rejection interna al KEM).
                let k = self.decapsulate_slice(msg).map_err(|_| Fail)?;
                output.push(k.as_slice());
                Ok(())
            }
        }
        impl EncapKey for ml_kem::EncapsulationKey<$mlkem> {
            const PUBKEY_LEN: usize = $pk_len;
            const CIPHERTEXT_LEN: usize = $ctext_len;

            fn decode(input: &[u8]) -> Result<Self, Fail> {
                // ml-kem 0.3 valida gia' l'encoding della chiave come
                // richiesto da NIST FIPS-203 §7.2 (il workaround per
                // ml_kem < 3.0 non serve piu').
                Self::new_from_slice(input).map_err(|_| Fail)
            }

            fn encode(&self, output: &mut ByteVec) {
                output.push(self.to_bytes().as_slice());
            }

            fn encapsulate(
                &self,
                rng: &mut DynRandom,
                msg: &mut ByteVec,
                secret_key: &mut ByteVec,
            ) -> Result<(), Fail> {
                // ml-kem 0.3: encapsulate_with_rng e' infallibile.
                let (ctext, ss) = self.encapsulate_with_rng(rng);
                msg.push(ctext.as_slice());
                secret_key.push(ss.as_slice());
                Ok(())
            }
        }
    }
}

define_mlkem_imp! {
    mlkem: ml_kem::MlKem768,
    pk_len: 1184,
    ctext_len: 1088
}

define_mlkem_imp! {
    mlkem: ml_kem::MlKem1024,
    pk_len: 1568,
    ctext_len: 1568
}

/// "Hybrid" KEM made by concatenating two underlying KEMs.
///
/// Public keys are encoded by concatenating the underlying KEM public keys;
/// ciphertexts are generated by concatenating the underlying ciphertexts;
/// shared secrets are generated by concatenating the underling shared secrets.
///
/// **WARNING**: This is not a secret KEM construction in the general case.
/// It's okay for TLS, which is how it's used here, but don't use it anywhere else.
pub(crate) struct ConcatHybrid<E1, E2>(pub(crate) E1, pub(crate) E2);

impl<E1: EncapKey, E2: EncapKey> EncapKey for ConcatHybrid<E1, E2> {
    const PUBKEY_LEN: usize = E1::PUBKEY_LEN + E2::PUBKEY_LEN;
    const CIPHERTEXT_LEN: usize = E1::CIPHERTEXT_LEN + E2::CIPHERTEXT_LEN;

    fn decode(input: &[u8]) -> Result<Self, Fail> {
        if input.len() != Self::PUBKEY_LEN {
            return Err(Fail);
        }
        let (input1, input2) = input.split_at(E1::PUBKEY_LEN);
        // NOTE: The early exit here is not constant-time, but that's
        // not a problem for this key exchange.
        Ok(Self(E1::decode(input1)?, E2::decode(input2)?))
    }
    fn encode(&self, output: &mut ByteVec) {
        self.0.encode(output);
        self.1.encode(output);
    }
    fn encapsulate(
        &self,
        rng: &mut DynRandom,
        msg: &mut ByteVec,
        secret_key: &mut ByteVec,
    ) -> Result<(), Fail> {
        // NOTE: The early exit here is not constant-time, but that's
        // not a problem for this key exchange.
        self.0.encapsulate(rng, msg, secret_key)?;
        self.1.encapsulate(rng, msg, secret_key)?;
        Ok(())
    }
}

impl<D1: DecapKey, D2: DecapKey> DecapKey for ConcatHybrid<D1, D2> {
    type PublicKey = ConcatHybrid<D1::PublicKey, D2::PublicKey>;
    const SECRET_LEN: usize = D1::SECRET_LEN + D2::SECRET_LEN;

    fn from_rng(rng: &mut DynRandom) -> (Self, Self::PublicKey) {
        let (sk1, pk1) = D1::from_rng(rng);
        let (sk2, pk2) = D2::from_rng(rng);
        (Self(sk1, sk2), ConcatHybrid(pk1, pk2))
    }

    fn decapsulate(self, msg: &[u8], output: &mut ByteVec) -> Result<(), Fail> {
        if msg.len() != Self::PublicKey::CIPHERTEXT_LEN {
            return Err(Fail);
        }
        let (msg1, msg2) = msg.split_at(D1::PublicKey::CIPHERTEXT_LEN);
        // NOTE: The early exit here is not constant-time, but that's
        // not a problem for this key exchange.
        self.0.decapsulate(msg1, output)?;
        self.1.decapsulate(msg2, output)?;
        Ok(())
    }
}

impl<E1: EncapKey, E2: EncapKey> ConcatHybrid<E1, E2> {
    /// Given an encoded public key, return the two component parts of that public key.
    ///
    /// # Panics
    ///
    /// Panics if the provided key is too short.
    pub(crate) fn split_pubkey(pk: &[u8]) -> (&[u8], &[u8]) {
        pk.split_at(E1::PUBKEY_LEN)
    }
}
